import React, { useEffect, useRef, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import './css/DashboardLayout.css';

function buildNavItems({ isWaiter, isChef, isCashier, isManager, isAdmin }) {
  const items = [];

  if (isWaiter) items.push({ type: 'link', path: '/waiter', icon: '📝', label: 'Tomar Pedido' });
  if (isChef) items.push({ type: 'link', path: '/kitchen', icon: '👨‍🍳', label: 'Cocina' });
  if (isCashier) items.push({ type: 'link', path: '/cashier', icon: <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-circle-dollar-sign-icon lucide-circle-dollar-sign"><circle cx="12" cy="12" r="10"/><path d="M16 8h-6a2 2 0 1 0 0 4h4a2 2 0 1 1 0 4H8"/><path d="M12 18V6"/></svg>, label: 'Caja' });

  if (isManager) {
    items.push({ type: 'link', path: '/admin/dashboard', icon: '📊', label: 'Dashboard' });
    items.push({
      type: 'group',
      key: 'menu',
      icon: <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg>,
      label: 'Menú',
      items: [
        { path: '/admin/menu', icon: <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg>, label: 'Gestionar Menú' },
        { path: '/admin/categories', icon: '🗂️', label: 'Categorías' },
        { path: '/admin/modifiers', icon: '⚙️', label: 'Modificadores' },
      ],
    });
    items.push({
      type: 'group',
      key: 'operacion',
      icon: '🏬',
      label: 'Operación',
      items: [
        { path: '/admin/tables', icon: '🪑', label: 'Mesas' },
        { path: '/admin/reservations', icon: '📅', label: 'Reservas' },
      ],
    });
    items.push({ type: 'link', path: '/admin/reports', icon: '📈', label: 'Reportes' });
  }

  if (isAdmin) {
    items.push({ type: 'link', path: '/admin/users', icon: '👥', label: 'Usuarios' });
  }

  return items;
}

const DashboardLayout = ({ children }) => {
  const { user, logout, isAdmin, isManager, isCashier, isChef, isWaiter } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [drawerOpen, setDrawerOpen] = useState(false);
  const [drawerExpandedGroup, setDrawerExpandedGroup] = useState(null);
  const [openDesktopGroup, setOpenDesktopGroup] = useState(null);
  const topbarRef = useRef(null);

  const navItems = buildNavItems({ isWaiter, isChef, isCashier, isManager, isAdmin });

  // Cerrar cajón y desplegables al cambiar de ruta
  useEffect(() => {
    setDrawerOpen(false);
    setOpenDesktopGroup(null);
  }, [location.pathname]);

  // Cerrar el desplegable de PC al hacer click afuera
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (topbarRef.current && !topbarRef.current.contains(e.target)) {
        setOpenDesktopGroup(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const isLinkActive = (path) => location.pathname.startsWith(path);
  const isGroupActive = (group) => group.items.some((i) => isLinkActive(i.path));

  const goTo = (path) => {
    navigate(path);
    setDrawerOpen(false);
    setOpenDesktopGroup(null);
  };

  const initials = user?.name?.charAt(0)?.toUpperCase() || '?';

  return (
    <div className="dash-shell">
      {/* ===================== Header + cajón (móvil / tablet) ===================== */}
      <header className="dash-mobile-header">
        <button
          className="dash-hamburger"
          onClick={() => setDrawerOpen(true)}
          aria-label="Abrir menú"
        >
          ☰
        </button>
        <span className="dash-brand"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg> Restaurant AR</span>
        <div style={{
          width: 36, height: 36, borderRadius: '50%',
          background: 'var(--color-primary)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontWeight: 700, color: 'var(--color-text-on-primary)', fontSize: 14,
        }}>
          {initials}
        </div>
      </header>

      <div className={`dash-drawer-backdrop ${drawerOpen ? 'open' : ''}`} onClick={() => setDrawerOpen(false)} />

      <aside className={`dash-drawer ${drawerOpen ? 'open' : ''}`}>
        <div className="dash-drawer-header">
          <span className="dash-brand"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg> Restaurant AR</span>
          <button className="dash-hamburger" onClick={() => setDrawerOpen(false)} aria-label="Cerrar menú">✕</button>
        </div>

        <nav className="dash-drawer-nav">
          {navItems.map((item) => {
            if (item.type === 'link') {
              return (
                <button
                  key={item.path}
                  className={`dash-navlink ${isLinkActive(item.path) ? 'active' : ''}`}
                  style={{ width: '100%', marginBottom: 2 }}
                  onClick={() => goTo(item.path)}
                >
                  <span>{item.icon}</span>
                  {item.label}
                </button>
              );
            }

            const expanded = drawerExpandedGroup === item.key;
            return (
              <div key={item.key}>
                <button
                  className={`dash-navlink ${isGroupActive(item) ? 'active' : ''}`}
                  style={{ width: '100%', marginBottom: 2, justifyContent: 'space-between' }}
                  onClick={() => setDrawerExpandedGroup(expanded ? null : item.key)}
                  aria-expanded={expanded}
                >
                  <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <span>{item.icon}</span>
                    {item.label}
                  </span>
                  <span style={{ fontSize: 11, transform: expanded ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }}>▾</span>
                </button>
                {expanded && (
                  <div className="dash-drawer-submenu">
                    {item.items.map((sub) => (
                      <button
                        key={sub.path}
                        className={`dash-navlink ${isLinkActive(sub.path) ? 'active' : ''}`}
                        style={{ width: '100%', marginBottom: 2 }}
                        onClick={() => goTo(sub.path)}
                      >
                        <span>{sub.icon}</span>
                        {sub.label}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </nav>

        <div className="dash-drawer-footer">
          <p style={{ color: 'var(--color-text)', fontSize: 13, fontWeight: 600 }}>{user?.name}</p>
          <p style={{ color: 'var(--color-text-secondary)', fontSize: 11, marginBottom: 12 }}>{user?.role?.name}</p>
          <button onClick={logout} className="btn" style={{ width: '100%', background: 'var(--color-bg-secondary)', color: 'var(--color-text)', border: '1px solid var(--color-border-strong)' }}>
            Cerrar Sesión
          </button>
        </div>
      </aside>

      {/* ===================== Barra superior con submenús (PC) ===================== */}
      <header className="dash-topbar" ref={topbarRef}>
        <span className="dash-brand" style={{ fontSize: 18 }}><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg> Restaurant AR</span>

        <nav className="dash-topnav">
          {navItems.map((item) => {
            if (item.type === 'link') {
              return (
                <button
                  key={item.path}
                  className={`dash-navlink ${isLinkActive(item.path) ? 'active' : ''}`}
                  onClick={() => goTo(item.path)}
                >
                  <span>{item.icon}</span>
                  {item.label}
                </button>
              );
            }

            const open = openDesktopGroup === item.key;
            return (
              <div key={item.key} className="dash-dropdown">
                <button
                  className={`dash-navlink ${isGroupActive(item) ? 'active' : ''}`}
                  onClick={() => setOpenDesktopGroup(open ? null : item.key)}
                  aria-expanded={open}
                >
                  <span>{item.icon}</span>
                  {item.label}
                  <span style={{ fontSize: 10, marginLeft: 2 }}>▾</span>
                </button>
                {open && (
                  <div className="dash-dropdown-panel">
                    {item.items.map((sub) => (
                      <button
                        key={sub.path}
                        className={`dash-navlink ${isLinkActive(sub.path) ? 'active' : ''}`}
                        style={{ width: '100%' }}
                        onClick={() => goTo(sub.path)}
                      >
                        <span>{sub.icon}</span>
                        {sub.label}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </nav>

        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{ textAlign: 'right' }}>
            <p style={{ color: 'var(--color-text)', fontSize: 13, fontWeight: 600, lineHeight: 1.2 }}>{user?.name}</p>
            <p style={{ color: 'var(--color-text-secondary)', fontSize: 11 }}>{user?.role?.name}</p>
          </div>
          <div style={{
            width: 36, height: 36, borderRadius: '50%',
            background: 'var(--color-primary)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontWeight: 700, color: 'var(--color-text-on-primary)', fontSize: 14, flexShrink: 0,
          }}>
            {initials}
          </div>
          <button
            onClick={logout}
            className="btn"
            style={{ background: 'var(--color-bg-secondary)', color: 'var(--color-text)', border: '1px solid var(--color-border-strong)', padding: '8px 14px' }}
          >
            Salir
          </button>
        </div>
      </header>

      {/* ===================== Contenido ===================== */}
      <main className="dash-content">
        {children}
      </main>
    </div>
  );
};

export default DashboardLayout;
